$('cardsSave').onclick = async ()=>{
  const msg = $('cardsMsg');
  if(CARDS.some(c => !(c.title || '').trim())){ msg.className = 'savemsg err'; msg.textContent = 'Every card needs a name.'; return; }
  if(CARDS.some(c => c.url && c.url.trim() && !urlOk(normalizeUrl(c.url)))){ msg.className = 'savemsg err'; msg.textContent = 'One of the links does not look right. Nothing was saved.'; return; }
  const out = CARDS.map(c => {
    const d = { ...c };
    d.title = d.title.trim();
    if(d.url) d.url = normalizeUrl(d.url);
    if(d.t === 'list') d.items = (d.items || []).filter(i => i.n && i.n.trim());
    if(d.t === 'schedule'){ const days = {}; SP_DAYS.forEach(([k]) => { const t = ((d.days || {})[k] || '').trim(); if(t) days[k] = t; }); d.days = days; }
    return d;
  });
  msg.className = 'savemsg'; msg.textContent = 'Saving…';
  $('cardsSave').disabled = true;
  try {
    const { data, error } = await withTimeout(db.rpc('set_venue_cards', { p_venue_id: V, p_key: K, p_cards: out.length ? out : null, p_pass: P }), 12000);
    if (error) throw new Error();
    // schema 6 answers { ok, cards } with the cleaned set; an older database answers true
    if (data && data.ok === false) throw new Error(data.error || 'refused');
    if (data !== true && !(data && data.ok === true)) throw new Error();
    CARDS = (data && Array.isArray(data.cards)) ? data.cards : out;
    cardClearDraft();
    DIRTY.cards = false;
    CARD_OPEN = -1; CARD_CONFIRM = -1;   // saving closes whatever was open
    renderCards();
    msg.className = 'savemsg ok'; msg.textContent = 'Live on your tables now.';
  } catch(e){
    setSaveState('cards', 'cardsSave', 'Save');
    msg.className = 'savemsg err';
    msg.textContent = e.message === 'locked' ? 'Too many passphrase tries. Wait fifteen minutes, then reload this page.'
      : (e.message === 'need_pass' || e.message === 'bad_key') ? 'Your link or passphrase no longer matches. Reload this page and sign in again.'
      : 'Could not save. Check your connection and try again.';
  }
};
renderCards();  // real values land when the stats call resolves

// Two different jobs here. The scheme allowlist (http, https, mailto, tel) is
// the safety measure: this link is tapped by every diner at the venue, so
// javascript: and data: must never survive. Adding https:// to a bare domain
// is only convenience, because owners type "mysite.com/menu" and a bare domain
// in an href resolves as a path on the app domain. mailto: and tel: are kept
// exactly as typed, so "call to reserve" and "email us" links work.
function normalizeUrl(u){
  const s = String(u || '').trim();
  if (!s) return '';
  if (/^(mailto|tel):/i.test(s)) return s;
  return /^[a-z][a-z0-9+.-]*:\/\//i.test(s) ? s : 'https://' + s;
}
function urlOk(s){
  if (s.length > 500) return false;
  if (/^mailto:/i.test(s)) return /^mailto:[^\s@]+@[^\s@]+\.[^\s@]+$/i.test(s);
  if (/^tel:/i.test(s))    return /^tel:[+0-9().-]{5,}$/i.test(s);
  return /^https?:\/\/[^\/\s]+\.[^\/\s]+/i.test(s);
}

// Internal game ids -> diner-facing names. Order here is display order.
const GAME_LIB = [
  { id:'who_knows_who',        name:'Who Knows Who',    sub:'groups, pass the phone' },
  { id:'guess_the_split',    name:'Guess the Split',  sub:'solo or up to 8' },
  { id:'who_invited_you', name:'Who Invited You?', sub:'3 to 8 players' },
  { id:'wordy',           name:'Wordy',            sub:'solo word puzzle' },
  { id:'trivia',          name:'Trivia',           sub:'solo or vs. up to 8' },
  { id:'fortune_teller',  name:'Fortune Teller',   sub:'solo, quick read' },
  { id:'all_talk',        name:'All Talk',         sub:'2 to 8, bid and prove' },
  { id:'cornhole',        name:'Cornhole',         sub:'bag toss, teams or solo' },
  { id:'quick_pour',      name:GNAME.quick_pour,       sub:'timed bar game, solo' },
  { id:'exquisite_corpse', name:'Exquisite Corpse',  sub:'2 or 3, pass and draw' },
  { id:'sketch_chain',    name:GNAME.sketch_chain, sub:'2 to 8, draw and guess' },
  // excl: venue-exclusive (38_horse_racing.sql). The row only renders for a
  // venue that already has the game, and the server refuses to ADD it from
  // this page, so unticking it here means only the platform can restore it.
  { id:'horse_racing',    name:'Horse Racing',     sub:'dice race betting, solo or up to 8', excl:true },
  { id:'ring_toss',       name:'Ring Toss',        sub:'swing the ring onto the hook, solo', excl:true },
];
function renderGameToggles(list){
  // rows render in the venue's SAVED order (33 preserves it server-side and
  // the app shows cards in this order); games not in the list follow after
  const saved = (list || []).filter(id => GAME_LIB.some(g => g.id === id));
  // exclusives never render as an addable row; they only appear if this
  // venue's saved list already carries them
  const order = saved.concat(GAME_LIB.filter(g => !saved.includes(g.id) && !g.excl).map(g => g.id));
  $('gameToggles').innerHTML = order.map(id=>{
    const g = GAME_LIB.find(x => x.id === id);
    const on = !list || !list.length || list.includes(g.id);
    return `<div class="gamerow" data-id="${g.id}">
      <label><input type="checkbox" value="${g.id}" ${on?'checked':''}><span class="gtext"><span class="gname">${g.name}</span><span class="gsub">${g.sub}</span></span></label>
      <span class="gmove"><button type="button" class="iconbtn" data-mv="-1" aria-label="Move ${g.name} up">${ARR_UP}</button><button type="button" class="iconbtn" data-mv="1" aria-label="Move ${g.name} down">${ARR_DOWN}</button></span>
    </div>`;
  }).join('');
  // an unsaved draft from an evicted tab wins over the server copy
  try {
    const d = JSON.parse(localStorage.getItem('st_owner_games_' + V) || 'null');
    if (Array.isArray(d) && d.length){
      const box = $('gameToggles');
      d.forEach(x => { const row = box.querySelector('.gamerow[data-id="' + x.id + '"]'); if(row){ row.querySelector('input').checked = !!x.on; box.appendChild(row); } });
      markDirty('games', 'gamesSave', 'Save', 'gamesMsg');
    }
  } catch(e){}
  const gamesChanged = ()=>{
    try { localStorage.setItem('st_owner_games_' + V, JSON.stringify([...document.querySelectorAll('#gameToggles .gamerow')].map(r => ({ id: r.dataset.id, on: r.querySelector('input').checked })))); } catch(e){}
    markDirty('games', 'gamesSave', 'Save', 'gamesMsg');
  };
  document.querySelectorAll('#gameToggles input[type=checkbox]').forEach(i => i.addEventListener('change', gamesChanged));
  document.querySelectorAll('#gameToggles .gmove button').forEach(b => b.onclick = ()=>{
    const row = b.closest('.gamerow');
    if (b.dataset.mv === '-1' && row.previousElementSibling) row.parentNode.insertBefore(row, row.previousElementSibling);
    if (b.dataset.mv === '1'  && row.nextElementSibling)     row.parentNode.insertBefore(row.nextElementSibling, row);
    gamesChanged();
  });
  setSaveState('games', 'gamesSave', 'Save');
}
$('gamesSave').onclick = async () => {
  const ids = [...document.querySelectorAll('#gameToggles input:checked')].map(i=>i.value);
  const msg = $('gamesMsg');
  if (!ids.length){
    msg.className='savemsg err'; msg.textContent='Keep at least one game on.';
    setTimeout(()=>{ msg.textContent=''; }, 4000);
    return;
  }
  msg.className='savemsg'; msg.textContent='Saving…';
  try {
    const { data, error } = await withTimeout(db.rpc('set_venue_games', { p_venue_id: V, p_key: K, p_games: ids, p_pass: P }), 12000);
    if (error || data !== true) throw new Error(data === false ? 'refused' : '');
    try { localStorage.removeItem('st_owner_games_' + V); } catch(e){}
    DIRTY.games = false; setSaveState('games', 'gamesSave', 'Save');
    msg.className='savemsg ok'; msg.textContent='Live on your tables now.';
  } catch(e){
    msg.className='savemsg err'; msg.textContent = e.message === 'refused' ? 'Saved nothing: your link or passphrase no longer matches. Reload this page and sign in again.' : 'Could not save. Check your connection and try again.';
  }
};

/* Optional passphrase (29_owner_passphrase.sql). Most venues have none and
   never see any of this. When one is set, the server answers
   {"need_pass": true} until the right passphrase arrives; we remember it
   per device so an owner types it roughly once, ever. */
let P = null;
const PASS_K = 'st_opass_' + V;
try {
  P = sessionStorage.getItem(PASS_K) || null;
  if(!P){
    const raw = localStorage.getItem(PASS_K);
    if(raw){
      let d = null; try { d = JSON.parse(raw); } catch(e){}
      if(d && d.p && d.exp > Date.now()) P = d.p;          // remembered device, still inside its 30 days
      else localStorage.removeItem(PASS_K);                  // expired, or the pre-build-23 plain string
    }
  }
} catch(e){}
function rememberPass(p, device){
  P = p;
  try {
    sessionStorage.setItem(PASS_K, p);
    if(device) localStorage.setItem(PASS_K, JSON.stringify({ p, exp: Date.now() + 30 * 864e5 }));
    else localStorage.removeItem(PASS_K);
  } catch(e){}
}
const REPORT_HREF = 'report.html?v=' + encodeURIComponent(V || '') + '&k=' + encodeURIComponent(K || '');
if($('liveAppLink')) $('liveAppLink').href = 'app.html?v=' + encodeURIComponent(V || '');   // the diner app, exactly as a scanned card opens it
if($('reportBtn')) $('reportBtn').href = REPORT_HREF;
if($('reportBtn2')) $('reportBtn2').href = REPORT_HREF;

/* Two halves: "My Stats" (read) and "App Settings" (edit). The hash remembers
   the tab, so an evicted phone tab reloads where the owner was. */
function showTab(which){
  const app = which === 'app';
  $('paneMonth').classList.toggle('on', !app); $('paneApp').classList.toggle('on', app);
  $('tabMonthBtn').classList.toggle('on', !app); $('tabAppBtn').classList.toggle('on', app);
  $('tabMonthBtn').setAttribute('aria-selected', String(!app)); $('tabAppBtn').setAttribute('aria-selected', String(app));
  try { history.replaceState(null, '', location.pathname + location.search + (app ? '#app' : '#month')); } catch(e){}
}
// switching tabs starts the new pane at the top; the first paint keeps the
// browser's own scroll position (a reload should not jump)
$('tabMonthBtn').onclick = ()=>{ showTab('month'); window.scrollTo(0, 0); };
$('tabAppBtn').onclick = ()=>{ showTab('app'); window.scrollTo(0, 0); };
showTab(location.hash === '#app' ? 'app' : 'month');



function showPassGate(wrong, locked){
  $('page').style.display = 'none';
  $('msg').style.display = 'block';
  $('msgTitle').textContent = locked ? 'Take a breather' : 'One more thing';
  $('msgBody').innerHTML = '';
  const wrap = document.createElement('div');
  if(locked){
    wrap.innerHTML = '<p>Too many passphrase tries. Wait fifteen minutes, then open this link again. If you forgot the passphrase, ask ' + esc(CFG.brandName) + ' to reset it.</p>';
    $('msgBody').appendChild(wrap);
    return;
  }
  // a real form, so the phone's password manager offers to save it (keyed by
  // the venue id in the hidden username field)
  wrap.innerHTML = `
    <p style="margin-bottom:14px">${wrong ? 'That passphrase did not match. Try again, or ask ' + esc(CFG.brandName) + ' if you forgot it.' : 'This dashboard is protected by a passphrase.'}</p>
    <form id="passForm" autocomplete="on">
      <input type="text" name="username" autocomplete="username" value="${esc(V || '')}" readonly tabindex="-1" aria-hidden="true" style="position:absolute;left:-9999px;width:1px;height:1px;opacity:0" />
      <input type="password" id="passInput" name="password" autocomplete="current-password" style="width:100%;max-width:280px;padding:12px 14px;font-size:16px;border:1px solid rgba(22,17,10,.2);border-radius:12px" />
      <label style="display:flex;align-items:center;gap:8px;margin:12px auto 0;max-width:280px;font-size:14px;color:var(--ink-dim);cursor:pointer"><input type="checkbox" id="passKeep" checked> Remember this device for 30 days</label>
      <div style="margin-top:12px"><button id="passGo" class="btn" type="submit" style="padding:12px 26px">Open dashboard</button></div>
    </form>`;
  $('msgBody').appendChild(wrap);
  $('passForm').onsubmit = e=>{ e.preventDefault(); const p = $('passInput').value.trim(); if(p) load(p, $('passKeep').checked); };
  $('passInput').focus();
}

async function load(tryPass, keepDevice){
  if (!V || !K){ showMsg('Missing link details', 'Open this page using the full owner link you were given.'); return; }
  const pass = tryPass !== undefined ? tryPass : P;
  showMsg('', tryPass !== undefined ? 'Checking…' : 'Loading your dashboard…');
  let res;
  try { res = await withTimeout(db.rpc('get_owner_stats', { p_venue_id: V, p_key: K, p_pass: pass }), 12000); }
  catch(e){ showMsg('One sec', 'We could not reach the server. Check your connection and reload this page.'); return; }
  if (res.error){ showMsg('One sec', 'We could not reach the server. Check your connection and reload this page.'); return; }
  if (!res.data){ showMsg('That link is not valid', 'This owner link does not match. Check for a truncated URL, or ask ' + CFG.brandName + ' for a fresh link.'); return; }
  if (res.data.need_pass){ showPassGate(pass != null, !!res.data.locked); return; }
  if (tryPass !== undefined) rememberPass(tryPass, !!keepDevice);
  $('msg').style.display = 'none';
  $('page').style.display = '';
  render(res.data);
}

function extractSwatches(img){
  const c=document.createElement('canvas'); c.width=40; c.height=40;
  const x=c.getContext('2d'); x.drawImage(img,0,0,40,40);
  const d=x.getImageData(0,0,40,40).data, tally={};
  for(let i=0;i<d.length;i+=4){
    if(d[i+3]<140) continue;                                  // transparent
    const r=d[i],g=d[i+1],b=d[i+2];
    const max=Math.max(r,g,b), min=Math.min(r,g,b);
    if(max>235&&min>215) continue;                            // near white
    if(max<35) continue;                                      // near black
    const k=[r,g,b].map(v=>Math.round(v/32)*32).join(',');
    tally[k]=(tally[k]||0)+1;
  }
  return Object.entries(tally).sort((a,b)=>b[1]-a[1]).slice(0,5)
    .map(([k])=>'#'+k.split(',').map(v=>(+v).toString(16).padStart(2,'0')).join(''));
}

/* The page wears the venue's colors: accent everywhere the dashboard uses
   its accent, and when the venue's app runs a dark or colored header the
   page background matches it (a white logo then reads here the way it does
   in the app). White venues change nothing. */
function applyVenueTheme(b){
  if(/^#[0-9a-f]{6}$/i.test(b.accent || '')){
    document.documentElement.style.setProperty('--accent', b.accent);
    document.documentElement.style.setProperty('--on-accent', readableOn(b.accent));
  }
  const bg = b.header_bg || (b.dark_mode ? '#0b0a09' : null);
  if(!bg) return;
  document.body.style.background = bg;
  if(readableOn(bg) === '#ffffff') document.body.classList.add('vd');
}

function initCardSection(v){
  if(!v || !v.id || !$('cardSec')) return;
  $('cardSec').style.display = '';
  mountCardDesigner($('cardHost'), v, {
    base: location.origin,
    msgClass: 'savemsg',
    swatches: extractSwatches,
    onDirty: b => { DIRTY.card = b; },
    save: async card => {
      const { data, error } = await withTimeout(db.rpc('set_venue_card', { p_venue_id: V, p_key: K, p_card: card, p_pass: P }), 12000);
      if (error) throw new Error();
      if (data && data.ok === false) throw new Error(data.error || 'refused');
      if (data !== true && !(data && data.ok === true)) throw new Error();
      return (data && data.card) || card;
    },
  });
}

let BRAND = null;
async function loadBrand(){
  if(!V) return;
  try {
    const { data } = await db.from('public_venues').select('*').eq('id', V).maybeSingle();
    if(data){
      BRAND = data;
      applyVenueTheme(data);
      initCardSection(data);
    }
  } catch(e){}
}
loadBrand();


/* platform branding from config: tab title, wordmark, favicon */
(function(){
  document.title = CFG.brandName + ' · Owner view';
  const mk = document.querySelector('.wm-mark'), nm = document.querySelector('.wm-name');
  const initial = (CFG.brandName || '?').trim().charAt(0).toUpperCase();
  const logoSvg = (typeof CFG.logoSvg === 'string' && CFG.logoSvg.trim().startsWith('<svg')) ? CFG.logoSvg : '';
  const iconUrl = (typeof CFG.iconUrl === 'string' && CFG.iconUrl) ? CFG.iconUrl : '';
  const logoUrl = (typeof CFG.logoUrl === 'string' && CFG.logoUrl) ? CFG.logoUrl : '';
  const wm = mk && mk.closest('.wordmark');
  // a full logo image replaces the mark+name pair; an icon image stands in
  // for the mark; inline SVG and the generated initial remain the fallbacks
  if(logoUrl && wm){ wm.innerHTML = '<img class="wm-img" src="' + logoUrl.replace(/"/g, '&quot;') + '" alt="' + String(CFG.brandName || '').replace(/"/g, '&quot;') + '">'; }
  else {
    if(mk){ if(logoSvg){ mk.innerHTML = logoSvg; mk.style.background = 'transparent'; } else if(iconUrl){ mk.innerHTML = '<img src="' + iconUrl.replace(/"/g, '&quot;') + '" alt="">'; mk.style.background = 'transparent'; } else { mk.textContent = initial; if(/^#[0-9a-f]{6}$/i.test(CFG.accent || '')) mk.style.background = CFG.accent; } }
    if(nm) nm.textContent = CFG.brandName;
  }
  const fav = document.querySelector('link[rel="icon"]');
  const acc = /^#[0-9a-f]{6}$/i.test(CFG.accent || '') ? CFG.accent : '#3a6ea5';
  if(fav) fav.href = iconUrl || 'data:image/svg+xml,' + encodeURIComponent(logoSvg || '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect x="6" y="6" width="52" height="52" rx="12" fill="' + acc + '"/><text x="32" y="44" font-family="sans-serif" font-size="34" font-weight="800" fill="#fff" text-anchor="middle">' + initial + '</text></svg>');
})();

load();
